INSERT INTO evento VALUES ('evt-p98wsr', '2026-08-27 21:29:28.476323', 'Gustavo Vidal', 'decisao', 'dec-sk86tq', '{"alt": ["incluir termo de equidade na funcao objetivo desde ja: penalizaria as solucoes da fase inicial por um criterio que o mercado nascente nao comporta"], "just": "na fase inicial de implantacao o transporte eVTOL nao sera amplamente acessivel; o grupo reconhece o fator (Gini de acessibilidade na literatura pos-2023) mas o considera relevante apenas num cenario futuro de democratizacao do modo, se houver; discussao levantada pela pesquisa profunda de fatores", "status": "vigente", "titulo": "Equidade de acesso: fator avaliado e deliberadamente descartado nesta fase"}');
