INSERT INTO evento VALUES ('evt-zgalxi', '2026-09-01 17:22:24.074259', 'Italo Rabelo', 'fonte', 'fon-n0fj83', '{"cobertura": "1603 helipontos privados no Brasil, 185 no municipio de Sao Paulo; traz codigo OACI, CIAD, coordenadas, tipo, dimensao da area de pouso, resistencia do pavimento e regra de voo diurna e noturna", "formato": "CSV latin-1, separador ponto-e-virgula, decimal por virgula, primeira linha com data de geracao", "limitacoes": "so helipontos privados: nao cobre helipontos publicos nem helidecks; resistencia do pavimento e o valor cadastral, nao laudo estrutural; nao traz restricao de espaco aereo, PZR nem rampa de aproximacao livre", "origem": "https://sistemas.anac.gov.br/dadosabertos/Aerodromos/Aerodromos Privados/Lista de aerodromos privados/Heliponto/Helipontos.csv", "titulo": "Cadastro de helipontos privados da ANAC"}');
INSERT INTO evento VALUES ('evt-k2bao4', '2026-09-01 17:22:24.640330', 'Italo Rabelo', 'fonte', 'fon-8xmejy', '{"cobertura": "94 estacoes em operacao no municipio de Sao Paulo, das empresas Metro e ViaQuatro, com linha e situacao operacional", "formato": "GeoJSON de pontos, um feature por estacao", "limitacoes": "nao inclui CPTM, terminais de onibus (camada estacao_transbordo) nem estacoes projetadas; o ponto e o centroide cadastral da estacao, nao a laje ou area util disponivel para implantacao", "origem": "http://wfs.geosampa.prefeitura.sp.gov.br/geoserver/geoportal/wfs (WFS 1.0.0, GetFeature, srsName=EPSG:4326)", "titulo": "Estacoes de metro do GeoSampa (camada geoportal:estacao_metro)"}');
INSERT INTO evento VALUES ('evt-3d2nxe', '2026-09-01 17:23:05.363399', 'Italo Rabelo', 'decisao', 'dec-5hbw2z', '{"alt": ["so helipontos existentes: barato e regulatoriamente seguro, mas cego ao acesso terrestre e concentrado no eixo Faria Lima-Itaim-Berrini", "grade regular de pontos sobre a cidade: cobre o espaco de forma neutra, mas nenhum candidato tem custo nem viabilidade defensavel"], "just": "o enunciado 2.2 diz que o acesso terrestre domina a cadeia porta-a-porta, entao um conjunto so de helipontos herda a geografia da aviacao executiva e nao a da mobilidade da cidade; as duas camadas entram no mesmo conjunto de decisao com custo de implantacao distinto (existente x a implantar), o que deixa o trade-off entre custo baixo e acesso bom explicito para o modelo em vez de resolvido na montagem do conjunto", "status": "vigente", "titulo": "Conjunto de candidatos em duas camadas: helipontos existentes e estacoes de metro como sitios a implantar"}');
INSERT INTO evento VALUES ('evt-6iclc5', '2026-09-01 17:23:06.024426', 'Italo Rabelo', 'decisao', 'dec-0cmfmg', '{"alt": ["2,4 t (classe Joby S4): mantem 183 helipontos, mas assume a aeronave mais leve do mercado como referencia de projeto", "nao filtrar por resistencia e tratar reforco estrutural como custo de implantacao: mais fiel a engenharia, porem exige estimativa de custo de reforco que o grupo nao tem fonte para sustentar"], "just": "3,2 t e o limite de categoria de 7.000 lb em que se enquadram os eVTOL anunciados para operacao comercial em Sao Paulo (Archer Midnight, Vertical VX4); e o parametro que mais move o conjunto e nao e continuo: a 3,0 t sobram 183 dos 185 helipontos e a 3,2 t sobram 150, porque 3,0 t e o valor de projeto mais comum das coberturas da cidade, entao a escolha da aeronave de referencia decide um terco do conjunto e precisa estar declarada, nao implicita", "status": "vigente", "titulo": "MTOW de referencia de 3,2 t como limiar de elegibilidade dos helipontos"}');
INSERT INTO evento VALUES ('evt-1uj49d', '2026-09-01 17:23:07.111416', 'Italo Rabelo', 'decisao', 'dec-hs0npv', '{"alt": ["colapsar cada grupo em um unico candidato: reduz a instancia de 279 para 233, mas apaga infraestrutura distinta e real antes de a formulacao decidir"], "just": "a mediana da distancia ao heliponto mais proximo e 235 m e 60 dos 185 tem vizinho a menos de 150 m; colapsar esses grupos e reducao de instancia, que o enunciado 2.5 trata como escolha de modelagem e cabe a formulacao (tar-s26xcn), nao a montagem do dado; entregar agrupamento_id e representante_agrupamento como colunas permite as duas leituras sem reprocessar", "status": "vigente", "titulo": "Agrupamento espacial a 150 m entra como coluna do conjunto, nao como filtro"}');
INSERT INTO evento VALUES ('evt-8lh6fz', '2026-09-01 17:23:37.332550', 'Italo Rabelo', 'arquivo', 'arq-sp9p0e', '{"desc": "baixa o cadastro ANAC de helipontos e a camada de estacoes de metro do GeoSampa para dados/bruto, sem sobrescrever o que ja estiver la", "titulo": "app/01-baixa-candidatos.R"}');
