INSERT INTO evento VALUES ('evt-ib530n', '2026-09-01 18:21:09.816240', 'Italo Rabelo', 'decisao', 'dec-v5jmkk', '{"alt": ["manter elegivel e explicar a ressalva so no relatorio: o CSV circula sozinho entre os integrantes e entre grupos, e o nome da coluna e o que se le primeiro"], "just": "Sao Paulo nao tem vertiporto; os 279 registros sao lugares onde um vertiporto poderia ser implantado, e o cadastro da ANAC descreve heliponto para helicoptero, nao vertiporto para eVTOL; nomear a coluna de elegivel fazia um heliponto aprovado em tres campos cadastrais parecer apto a operar eVTOL, o que o dado nao sustenta: geometria FATO/TLOF pela dimensao de controle da aeronave, potencia eletrica de recarga, superficies de aproximacao sob norma de vertiporto e processamento de passageiros ficam todos fora do cadastro; as colunas passam a ser apto_triagem e infra_aeronautica, que dizem o que o dado de fato mede", "status": "vigente", "titulo": "Candidato e sitio de implantacao, nao vertiporto: a triagem cadastral nao afirma aptidao"}');
