INSERT INTO evento VALUES ('evt-asorut', '2026-09-01 18:58:45.930805', 'Italo Rabelo', 'decisao', 'dec-0cmfmg', '{"alt": ["2,4 t (classe Joby S4): mantem 183 helipontos, mas assume a aeronave mais leve do mercado como referencia de projeto", "nao filtrar por resistencia e tratar reforco estrutural como custo de implantacao: mais fiel a engenharia, porem exige estimativa de custo de reforco que o grupo nao tem fonte para sustentar"], "just": "3,2 t e o limite de categoria de 7.000 lb em que se enquadram os eVTOL anunciados para operacao comercial em Sao Paulo (Archer Midnight, Vertical VX4); e o parametro que mais move o conjunto e nao e continuo: a 3,0 t sobram 183 dos 185 helipontos e a 3,2 t sobram 150, porque 3,0 t e o valor de projeto mais comum das coberturas da cidade, entao o limiar decide 35 dos 185 helipontos (cerca de um quinto da camada, 13% do conjunto de 279) e precisa estar declarado, nao implicito", "status": "vigente", "titulo": "MTOW de referencia de 3,2 t como limiar de elegibilidade dos helipontos"}');
